const IMMEDIATE_SAFETY_REPORT_REASONS = new Set(["child-safety", "illegal-content", "self-harm"]);

function reportNeedsImmediateSafetyReview(report) {
  return IMMEDIATE_SAFETY_REPORT_REASONS.has(normalizeReportReason(report?.reason));
}

function reportQueueThresholds(
  ordinaryCap = MAX_REPORTS,
  immediateSafetyReserve = IMMEDIATE_SAFETY_REPORT_RESERVE,
  ordinaryByteCap = MAX_REPORT_BYTES,
  immediateSafetyByteReserve = IMMEDIATE_SAFETY_REPORT_BYTE_RESERVE
) {
  const ordinaryLimit = Math.max(0, Math.floor(Number(ordinaryCap) || 0));
  const reserve = Math.max(0, Math.floor(Number(immediateSafetyReserve) || 0));
  const ordinaryByteLimit = Math.max(0, Math.floor(Number(ordinaryByteCap) || 0));
  const byteReserve = Math.max(0, Math.floor(Number(immediateSafetyByteReserve) || 0));
  return {
    ordinaryLimit,
    hardLimit: ordinaryLimit + reserve,
    ordinaryByteLimit,
    hardByteLimit: ordinaryByteLimit + byteReserve,
  };
}

function reportQueueAdmissionLimits(
  candidate,
  ordinaryCap = MAX_REPORTS,
  immediateSafetyReserve = IMMEDIATE_SAFETY_REPORT_RESERVE,
  ordinaryByteCap = MAX_REPORT_BYTES,
  immediateSafetyByteReserve = IMMEDIATE_SAFETY_REPORT_BYTE_RESERVE,
  admissionReason = ""
) {
  if (!candidate || typeof candidate !== "object") return { count: 0, bytes: 0 };
  const thresholds = reportQueueThresholds(
    ordinaryCap,
    immediateSafetyReserve,
    ordinaryByteCap,
    immediateSafetyByteReserve
  );
  const limitsCandidate = admissionReason ? { reason: admissionReason } : candidate;
  return reportNeedsImmediateSafetyReview(limitsCandidate)
    ? { count: thresholds.hardLimit, bytes: thresholds.hardByteLimit }
    : { count: thresholds.ordinaryLimit, bytes: thresholds.ordinaryByteLimit };
}

function reportQueueAdmissionPlan(
  list,
  candidate,
  ordinaryCap = MAX_REPORTS,
  immediateSafetyReserve = IMMEDIATE_SAFETY_REPORT_RESERVE,
  ordinaryByteCap = MAX_REPORT_BYTES,
  immediateSafetyByteReserve = IMMEDIATE_SAFETY_REPORT_BYTE_RESERVE,
  { requirePreStateHeadroom = true, admissionReason = "" } = {}
) {
  if (!candidate || typeof candidate !== "object") return null;
  const candidateId = String(candidate.id || "").trim();
  if (!candidateId) return null;
  const limits = reportQueueAdmissionLimits(
    candidate,
    ordinaryCap,
    immediateSafetyReserve,
    ordinaryByteCap,
    immediateSafetyByteReserve,
    normalizeReportReason(admissionReason)
  );
  if (!limits.count || !limits.bytes) return null;
  // Compatibility callers may pass a list that already contains the exact
  // candidate object. Exclude only that reference when measuring pre-state;
  // a prior stored row with the same id remains charged for reattachment or
  // promotion headroom.
  const current = (Array.isArray(list) ? list : []).filter((report) => report !== candidate);
  if (requirePreStateHeadroom && current.length >= limits.count) return null;

  // Runtime reports have already been normalized and deduplicated at load.
  // Normalize only one row at a time here so an admission check never holds
  // two extra 40-48 MiB report graphs at once. Any unexpected duplicate in
  // current state fails closed rather than being consolidated during intake.
  let currentCompactBytes = 2; // Compact JSON array brackets.
  let existingCandidateIndex = -1;
  let existingCandidateBytes = 0;
  let existingCandidateDedupeKey = "";
  const reportIdSet = new Set();
  const reportIdByDedupeKey = new Map();
  for (let index = 0; index < current.length; index += 1) {
    const normalized = normalizeReport(current[index]);
    const reportId = String(normalized.id || "").trim();
    const dedupeKey = reportDuplicateSuppressionKey(normalized);
    if (!reportId || reportIdSet.has(reportId) || !dedupeKey || reportIdByDedupeKey.has(dedupeKey)) {
      return null;
    }
    reportIdSet.add(reportId);
    reportIdByDedupeKey.set(dedupeKey, reportId);
    const rowBytes = compactPersistedReportRecordBytes(normalized);
    if (index) currentCompactBytes += 1;
    currentCompactBytes += rowBytes;
    if (reportId === candidateId) {
      existingCandidateIndex = index;
      existingCandidateBytes = rowBytes;
      existingCandidateDedupeKey = dedupeKey;
    }
    if (requirePreStateHeadroom && currentCompactBytes >= limits.bytes) return null;
  }

  const normalizedCandidate = normalizeReport(candidate);
  if (String(normalizedCandidate.id || "").trim() !== candidateId) return null;
  const candidateDedupeKey = reportDuplicateSuppressionKey(normalizedCandidate);
  const candidateDedupeReportId = reportIdByDedupeKey.get(candidateDedupeKey);
  if (
    !candidateDedupeKey
    || (candidateDedupeReportId && candidateDedupeReportId !== candidateId)
    || (existingCandidateIndex >= 0 && existingCandidateDedupeKey !== candidateDedupeKey)
  ) {
    return null;
  }
  const candidateBytes = compactPersistedReportRecordBytes(normalizedCandidate);
  const prospectiveCount = current.length + (existingCandidateIndex >= 0 ? 0 : 1);
  if (prospectiveCount > limits.count) return null;
  const prospectiveCompactBytes = existingCandidateIndex >= 0
    ? currentCompactBytes - existingCandidateBytes + candidateBytes
    : currentCompactBytes + candidateBytes + (current.length ? 1 : 0);
  if (prospectiveCompactBytes > limits.bytes) return null;
  const kept = existingCandidateIndex >= 0
    ? current.map((report, index) => (index === existingCandidateIndex ? normalizedCandidate : report))
    : [...current, normalizedCandidate];
  return { reports: kept, compactBytes: prospectiveCompactBytes };
}

function retainReportQueueForSubmission(
  list,
  candidate,
  ordinaryCap = MAX_REPORTS,
  immediateSafetyReserve = IMMEDIATE_SAFETY_REPORT_RESERVE,
  ordinaryByteCap = MAX_REPORT_BYTES,
  immediateSafetyByteReserve = IMMEDIATE_SAFETY_REPORT_BYTE_RESERVE,
  options = {}
) {
  const plan = reportQueueAdmissionPlan(
    list,
    candidate,
    ordinaryCap,
    immediateSafetyReserve,
    ordinaryByteCap,
    immediateSafetyByteReserve,
    options
  );
  if (!plan) return null;
  // Fresh ordinary intake stops at the ordinary threshold. Only an
  // immediate-safety candidate may use the protected reserve, and all fresh
  // intake stops at the hard count or byte threshold. Never make room by
  // deleting evidence or by charging JavaScript characters instead of the
  // exact compact persisted UTF-8 shape.
  return plan.reports;
}

function reportQueueCapacityFailure() {
  return {
    ok: false,
    status: 503,
    code: "report_queue_full",
    message: "Turnfeed's protected moderation queue is at capacity, so this report was not stored and nothing changed. Contact Turnfeed Support with the target URL or identifier. Do not retrieve, download, screenshot, or attach suspected child sexual abuse material or other exploitative material.",
  };
}

function reportEvidenceCapacityFailure() {
  return {
    ok: false,
    status: 503,
    code: "report_evidence_capacity",
    message: "Turnfeed could not safely preserve the moderation evidence required for this change because the protected review store is temporarily full. Nothing changed. Contact Turnfeed Support with the target URL or identifier.",
  };
}

function reportEvidenceMutationCapacityFailure(
  beforeReports,
  afterReports,
  {
    hardCountCap = MAX_REPORTS_HARD_CAP,
    hardByteCap = MAX_REPORT_BYTES_HARD_CAP,
  } = {}
) {
  if (beforeReports === afterReports) return null;
  const before = compactPersistedReportBytes(beforeReports);
  const after = compactPersistedReportBytes(afterReports);
  const beforeCount = Array.isArray(beforeReports) ? beforeReports.length : 0;
  const afterCount = Array.isArray(afterReports) ? afterReports.length : 0;
  const hardCountLimit = Math.max(0, Math.floor(Number(hardCountCap) || 0));
  const hardByteLimit = Math.max(0, Math.floor(Number(hardByteCap) || 0));
  const afterExceedsHardLimit = afterCount > hardCountLimit || after.bytes > hardByteLimit;
  const legacyStateDidNotGrow = afterCount <= beforeCount && after.bytes <= before.bytes;
  return afterExceedsHardLimit && !legacyStateDidNotGrow
    ? reportEvidenceCapacityFailure()
    : null;
}

