const REPEATED_CHAR_SPAM_RE = /(.)\1{11,}/i;

const REPEATED_WORD_SPAM_RE = /\b([a-z0-9]{2,})\b(?:[\s,.;:!?-]+\1\b){4,}/i;

const SYMBOL_ONLY_JUNK_RE = /^[\p{P}\p{S}\s]+$/u;

const POST_FILLER_ONLY_RE = /^(?:anyone here|anybody here|does (?:this|it) work|checking(?:\s+if)?\s+this works?|just testing|test post|testing(?:\s+this\s+out)?|bump|following|posting this here|just posting this here|random thought|hello there|hi there|gm everyone|good morning everyone)[.!?]*$/i;

const REPLY_FILLER_ONLY_RE = /^(?:just testing|test reply|testing|test|bump|following|subscribed|subbed|\+1|first|commenting(?:\s+(?:for reach|to follow))?|here for this|watching this|bookmarking|anyone here|anybody here)[.!?]*$/i;

const POST_COMMAND_ONLY_RE = /^(?:(?:i|we)\s+(?:want|need|would\s+like|am\s+trying|are\s+trying)\s+to\s+)?(?:create|make|write|draft|publish|compose|start)\s+(?:(?:a|an|my|new)\s+)?(?:turnfeed\s+)?post(?:\s+(?:on|in)\s+turnfeed)?(?:\s+(?:please|for\s+me))?[.!?]*$/i;

const REPLY_COMMAND_ONLY_RE = /^(?:(?:i|we)\s+(?:want|need|would\s+like|am\s+trying|are\s+trying)\s+to\s+)?(?:(?:create|make|write|draft|publish|compose|start)\s+(?:(?:a|an|my|new)\s+)?(?:turnfeed\s+)?reply|reply)(?:\s+(?:on|in)\s+turnfeed)?(?:\s+(?:please|for\s+me))?[.!?]*$/i;

const PUBLIC_VIOLENT_INTENT_RE = /\b(?:i|we)\s+(?:(?:want|intend|plan|need|would like)\s+to|(?:will|shall|am going to|are going to|going to))\s+(?<verb>kill|murder|stab|shoot|strangle|beat|attack|hurt|harm|seriously\s+harm)\s+(?<target>another person|a person|someone|somebody|people|them|him|her|you)\b/i;

const PUBLIC_NORWEGIAN_DIRECT_VIOLENT_INTENT_RE = /^(?:\.\s*|nå\s*:\s*)?jeg\s+planlegger\s+å\s+drepe\s+noen\s+i\s+kveld(?=$|[^\p{L}\p{N}])/u;

