function stableStringify(value) {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  const keys = Object.keys(value).sort();
  return `{${keys.map((k) => JSON.stringify(k) + ":" + stableStringify(value[k])).join(",")}}`;
}

function comparableContentText(text) {
  return String(text ?? "")
    .toLowerCase()
    .replace(/https?:\/\/\S+/g, " ")
    .replace(/[@#][\p{L}\p{N}_-]+/gu, " ")
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function adminPreviewPath({ postId = "", replyId = "", reportId = "" } = {}) {
  const next = new URL(ADMIN_PREVIEW_PATH, "http://localhost");
  const cleanPostId = String(postId ?? "").trim();
  const cleanReplyId = String(replyId ?? "").trim();
  const cleanReportId = String(reportId ?? "").trim();
  if (cleanPostId) next.searchParams.set("postId", cleanPostId);
  if (cleanReplyId) next.searchParams.set("replyId", cleanReplyId);
  if (cleanReportId) next.searchParams.set("reportId", cleanReportId);
  return `${next.pathname}${next.search}`;
}

function comparableInlineUrlKeys(text) {
  const matches = String(text ?? "").match(/https?:\/\/\S+/gi);
  if (!Array.isArray(matches) || !matches.length) return [];
  return Array.from(new Set(matches.map((rawUrl) => normalizeLinkPreviewKey(rawUrl)).filter(Boolean))).sort();
}

function comparableMediaIdentityKeys(media) {
  if (!Array.isArray(media) || !media.length) return [];
  const out = [];
  for (const item of media) {
    const normalized = normalizeMediaItem(item);
    if (!normalized) continue;
    const tokens = mediaAttachmentIdentityTokens(normalized);
    if (!tokens.length) continue;
    const type = String(normalized.type || "image").trim().toLowerCase() || "image";
    for (const token of tokens) out.push(`${type}:${token}`);
  }
  return Array.from(new Set(out)).sort();
}

function comparableDuplicateSignature({ text, kind = "post", media = [], quotePostId = "", targetPostId = "" } = {}) {
  const comparable = comparableContentText(text);
  if (!comparable) return "";
  const normalizedKind = kind === "reply" ? "reply" : "post";
  const signature = {
    kind: normalizedKind,
    text: comparable,
  };
  const inlineUrls = comparableInlineUrlKeys(text);
  if (inlineUrls.length) signature.inlineUrls = inlineUrls;
  if (normalizedKind === "post") {
    const mediaKeys = comparableMediaIdentityKeys(media);
    if (mediaKeys.length) signature.media = mediaKeys;
    const cleanQuotePostId = String(quotePostId || "").trim();
    if (cleanQuotePostId) signature.quotePostId = cleanQuotePostId;
  } else {
    const cleanTargetPostId = String(targetPostId || "").trim();
    if (cleanTargetPostId) signature.targetPostId = cleanTargetPostId;
  }
  return stableStringify(signature);
}

function contentSimilarityTokens(text) {
  const comparable = comparableContentText(text);
  if (!comparable) return [];
  return Array.from(
    new Set(
      comparable
        .split(" ")
        .filter((token) => token && token.length >= 3 && !LOW_SIGNAL_SIMILARITY_STOPWORDS.has(token))
    )
  );
}

function countInlineUrls(text) {
  const matches = String(text ?? "").match(/https?:\/\/\S+/gi);
  return Array.isArray(matches) ? matches.length : 0;
}

function inlineUrlsFromText(text) {
  const matches = String(text ?? "").match(/https?:\/\/\S+/gi);
  return Array.isArray(matches) ? matches : [];
}

function stripInlineUrls(text) {
  return String(text ?? "").replace(/https?:\/\/\S+/gi, " ").replace(/\s+/g, " ").trim();
}

function strongestInlineUrlHostRepeatCount(text) {
  const urls = inlineUrlsFromText(text);
  if (!urls.length) return 0;
  const hostCounts = new Map();
  for (const rawUrl of urls) {
    const normalized = normalizeLinkPreviewKey(rawUrl);
    if (!normalized) continue;
    try {
      const host = new URL(normalized).hostname.trim().toLowerCase();
      if (!host) continue;
      hostCounts.set(host, (hostCounts.get(host) || 0) + 1);
    } catch {}
  }
  let strongest = 0;
  for (const count of hostCounts.values()) strongest = Math.max(strongest, count);
  return strongest;
}

function excessiveInlineLinkSpamIssue(text, kind = "post") {
  const inlineUrlCount = countInlineUrls(text);
  if (!inlineUrlCount) return "";
  const normalizedKind = kind === "reply" ? "reply" : "post";
  const cleanWithoutUrls = comparableContentText(stripInlineUrls(text));
  const meaningfulTokens = contentSimilarityTokens(cleanWithoutUrls).length;
  const strongestHostRepeat = strongestInlineUrlHostRepeatCount(text);

  if (normalizedKind === "reply") {
    if (
      inlineUrlCount >= 2
      && (
        cleanWithoutUrls.length < 56
        || meaningfulTokens < 4
        || (strongestHostRepeat >= 2 && cleanWithoutUrls.length < 80)
      )
    ) {
      return "That reply is too link-heavy. Keep replies to one link unless you're adding more original context.";
    }
    return "";
  }

  if (
    inlineUrlCount >= 3
    && (
      cleanWithoutUrls.length < 64
      || meaningfulTokens < 6
      || (strongestHostRepeat >= 3 && cleanWithoutUrls.length < 96)
    )
  ) {
    return "That post is too link-heavy. Keep one or two links and add more of your own context.";
  }
  return "";
}

function postLooksGreetingOnly(text) {
  return /^(?:hello|hi|hey|yo|sup|gm|good morning|good afternoon|good evening|checking in|first post|test|testing)(?:\s+(?:everyone|all|turnfeed|feed|friends))?[.!?]*$/i.test(String(text ?? "").trim());
}

function textLooksLikeShortJunkToken(text) {
  const comparable = comparableContentText(text);
  if (!comparable || comparable.includes(" ")) return false;
  if (comparable.length < 5 || comparable.length > 8) return false;
  if (new Set(comparable).size <= 2) return true;
  if (/^([a-z]{2,3})\1+[a-z]?$/i.test(comparable)) return true;
  return false;
}

function textLooksObviousFiller(text, kind = "post") {
  const clean = String(text ?? "").trim();
  if (!clean) return true;
  if (SYMBOL_ONLY_JUNK_RE.test(clean)) return true;
  if (kind === "post") {
    return postLooksGreetingOnly(clean) || POST_FILLER_ONLY_RE.test(clean);
  }
  return REPLY_FILLER_ONLY_RE.test(clean);
}

function commandOnlyPublicTextIssue(text, kind = "post") {
  const clean = String(text ?? "").trim();
  if (!clean) return "";
  if (kind === "reply" ? REPLY_COMMAND_ONLY_RE.test(clean) : POST_COMMAND_ONLY_RE.test(clean)) {
    return kind === "reply"
      ? "That looks like a request to start a reply, not the exact public reply text. Provide the exact words to publish before sending."
      : "That looks like a request to start a post, not the exact public post text. Provide the exact words to publish before posting.";
  }
  return "";
}

function repeatedPhraseLoopJunk(text) {
  const comparable = comparableContentText(text);
  if (!comparable) return false;
  const tokens = comparable.split(" ").filter(Boolean);
  if (tokens.length < 6) return false;
  const maxUnitSize = Math.min(4, Math.floor(tokens.length / 3));
  for (let unitSize = 2; unitSize <= maxUnitSize; unitSize += 1) {
    if (tokens.length % unitSize !== 0) continue;
    const repeats = tokens.length / unitSize;
    if (repeats < 3) continue;
    const unit = tokens.slice(0, unitSize);
    let matches = true;
    for (let offset = unitSize; offset < tokens.length; offset += unitSize) {
      for (let i = 0; i < unitSize; i += 1) {
        if (tokens[offset + i] !== unit[i]) {
          matches = false;
          break;
        }
      }
      if (!matches) break;
    }
    if (matches) return true;
  }
  return false;
}

function lowVarietyJunkTokenPattern(text, kind = "post") {
  const comparable = comparableContentText(text);
  if (!comparable) return false;
  const tokens = comparable.split(" ").filter(Boolean);
  if (tokens.length < 6) return false;
  const uniqueTokens = new Set(tokens);
  const counts = new Map();
  for (const token of tokens) counts.set(token, (counts.get(token) || 0) + 1);
  let maxCount = 0;
  for (const count of counts.values()) maxCount = Math.max(maxCount, count);
  const dominantRatio = maxCount / tokens.length;
  if (uniqueTokens.size <= 2 && tokens.length >= 6 && dominantRatio >= 0.5) {
    return comparable.length >= 18;
  }
  if (kind === "reply" && uniqueTokens.size <= 3 && tokens.length >= 8 && dominantRatio >= 0.625) {
    return comparable.length >= 24;
  }
  if (kind === "post" && uniqueTokens.size <= 3 && tokens.length >= 10 && dominantRatio >= 0.6) {
    return comparable.length >= 28;
  }
  return false;
}

function repetitiveJunkTextIssue(text, kind = "post") {
  const clean = String(text ?? "").trim();
  if (!clean) return "";
  if (REPEATED_CHAR_SPAM_RE.test(clean) || REPEATED_WORD_SPAM_RE.test(clean)) {
    return kind === "reply"
      ? "That reply looks repetitive. Make it more specific before sending."
      : "That post looks repetitive. Make it more specific before publishing.";
  }
  if (repeatedPhraseLoopJunk(clean) || lowVarietyJunkTokenPattern(clean, kind)) {
    return kind === "reply"
      ? "That reply looks like repetitive junk. Add a concrete point before sending."
      : "That post looks like repetitive junk. Add a concrete point before publishing.";
  }
  return "";
}

function publicViolentIntentViews(text) {
  const matchView = moderationMatchView(text);
  const clean = matchView
    .replace(/\bi'll\b/g, "i will")
    .replace(/\bwe'll\b/g, "we will")
    .replace(/\bi'm\b/g, "i am")
    .replace(/\bwe're\b/g, "we are")
    .replace(/[^\p{L}\p{N}\s']/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
  return { matchView, clean };
}

function publicViolentIntentIssueFromViews({ matchView = "", clean = "" } = {}, kind = "post") {
  if (
    !clean
    || (
      !publicViolentIntentMatches(clean)
      && !PUBLIC_NORWEGIAN_DIRECT_VIOLENT_INTENT_RE.test(matchView)
    )
  ) {
    return "";
  }
  return kind === "reply"
    ? "Turnfeed can't save public replies that express an intent to kill or seriously harm another person. Rewrite it without a threat before publishing."
    : "Turnfeed can't save public posts that express an intent to kill or seriously harm another person. Rewrite it without a threat before publishing.";
}

function publicViolentIntentIssue(text, kind = "post") {
  return publicViolentIntentIssueFromViews(publicViolentIntentViews(text), kind);
}

function publicCorrectionHistoryCompositeIssue({
  currentText,
  correctionHistory,
  previousText,
  reason,
  kind = "post",
} = {}) {
  const normalizedKind = kind === "reply" ? "reply" : "post";
  const maxTextChars = normalizedKind === "reply" ? MAX_REPLY_CHARS : MAX_POST_CHARS;
  const boundedCurrentText = String(currentText ?? "").slice(0, maxTextChars);
  const history = normalizeCorrectionHistory(correctionHistory, maxTextChars);
  const boundedPreviousText = typeof previousText === "string"
    ? previousText.slice(0, maxTextChars)
    : "";
  const boundedReason = normalizeCorrectionReason(reason);
  const prospectiveHistory = boundedPreviousText
    ? [...history, {
      text: boundedPreviousText,
      ...(boundedReason ? { reason: boundedReason } : {}),
    }]
    : history;
  if (!prospectiveHistory.length) return "";

  const actualRenderOrder = [boundedCurrentText];
  const defensiveStructuredOrder = [boundedCurrentText];
  for (const entry of prospectiveHistory) {
    if (entry.reason) actualRenderOrder.push(entry.reason);
    actualRenderOrder.push(entry.text);
    defensiveStructuredOrder.push(entry.text);
    if (entry.reason) defensiveStructuredOrder.push(entry.reason);
  }
  const actualRenderOrderIssue = publicViolentIntentIssue(
    actualRenderOrder.join("\n"),
    normalizedKind,
  );
  const defensiveStructuredOrderIssue = publicViolentIntentIssue(
    defensiveStructuredOrder.join("\n"),
    normalizedKind,
  );
  if (!actualRenderOrderIssue && !defensiveStructuredOrderIssue) return "";
  return `Nothing was changed. This edit would make the public edit history for the ${normalizedKind} combine into an intent to kill or seriously harm someone. Rewrite the replacement text or optional author edit note before saving.`;
}

function publicCorrectionHistoryProjection(target, kind = "post", { preserve = false } = {}) {
  const normalizedKind = kind === "reply" ? "reply" : "post";
  const maxTextChars = normalizedKind === "reply" ? MAX_REPLY_CHARS : MAX_POST_CHARS;
  const correctionHistory = normalizeCorrectionHistory(target?.correctionHistory, maxTextChars);
  if (preserve || !correctionHistory.length) return { correctionHistory };
  const unsafeComposite = publicCorrectionHistoryCompositeIssue({
    currentText: target?.text,
    correctionHistory,
    kind: normalizedKind,
  });
  return unsafeComposite
    ? { correctionHistory: [], correctionHistoryUnavailable: true }
    : { correctionHistory };
}

function publicProfileTextSafetyIssue(text) {
  return publicViolentIntentIssue(text, "post")
    ? "Turnfeed can't save public profile text that expresses an intent to kill or seriously harm another person. Rewrite it without a threat before saving."
    : "";
}

function publicViolentIntentMatches(cleanText) {
  let remaining = String(cleanText || "");
  while (remaining) {
    const match = remaining.match(PUBLIC_VIOLENT_INTENT_RE);
    if (!match) return false;
    const verb = String(match.groups?.verb || "").trim().replace(/\s+/g, " ");
    const target = String(match.groups?.target || "").trim();
    const matchEnd = Math.max(0, Number(match.index || 0) + String(match[0] || "").length);
    const tail = remaining.slice(matchEnd).trim();
    if (verb === "shoot") {
      if (!violentIntentTargetIsPronoun(target) || !shootTailLooksBenign(tail)) return true;
    } else if (verb === "beat") {
      if (!violentIntentTargetIsPronoun(target) || !beatTailLooksBenign(tail)) return true;
    } else {
      return true;
    }
    // The first match was an allowed idiom. Continue through its tail so a
    // later direct threat cannot be masked by the benign phrase.
    remaining = tail;
  }
  return false;
}

function violentIntentTargetIsPronoun(target) {
  return /^(?:them|him|her|you)$/i.test(String(target || "").trim());
}

function shootTailLooksBenign(tail) {
  return /^(?:a|an|the)\s+(?:(?:quick|short|brief)\s+)?(?:message|email|text|dm|note|reply|reminder|update|details)\b/i.test(String(tail || "").trim());
}

function beatTailLooksBenign(tail) {
  const clean = String(tail || "").trim();
  return /^(?:at|in)\s+(?:(?:your|his|her|their)\s+own\s+game|(?:(?:a|an|the)\s+)?(?:board\s+game|card\s+game|video\s+game|ranked\s+match|game|match|competition|contest|tournament|race|debate|quiz|trivia|poll|election|chess|checkers|go|scrabble|poker|wordle|tennis|soccer|football|basketball|baseball|hockey|golf|mario\s+kart|rocket\s+league))\b/i.test(clean)
    || /^to\s+(?:the\s+)?(?:punch|finish|goal|deadline)\b/i.test(clean);
}

function textLooksThinForRepetition(text, kind = "post") {
  const clean = String(text ?? "").trim();
  const comparable = comparableContentText(clean);
  if (!comparable) return true;
  if (textLooksObviousFiller(clean, kind) || textLooksLikeShortJunkToken(clean)) return true;
  const tokens = comparable.split(" ").filter(Boolean);
  const uniqueTokens = new Set(tokens).size;
  const meaningfulTokens = contentSimilarityTokens(clean).length;
  const shortQuestion = /[?]\s*$/.test(clean);

  if (kind === "reply") {
    if (comparable.length <= 70 && meaningfulTokens <= 4) return true;
    if (tokens.length <= 9 && uniqueTokens <= 6 && comparable.length <= 90) return true;
    if (shortQuestion && meaningfulTokens <= 4 && comparable.length <= 80) return true;
    return false;
  }

  if (comparable.length <= 96 && meaningfulTokens <= 4) return true;
  if (tokens.length <= 10 && uniqueTokens <= 7 && comparable.length <= 120) return true;
  if (shortQuestion && meaningfulTokens <= 4 && comparable.length <= 120) return true;
  return false;
}

function contentSimilarityScore(a, b) {
  const cleanA = comparableContentText(a);
  const cleanB = comparableContentText(b);
  if (!cleanA || !cleanB) return 0;
  if (cleanA === cleanB) return 1;
  const shorter = cleanA.length <= cleanB.length ? cleanA : cleanB;
  const longer = shorter === cleanA ? cleanB : cleanA;
  if (shorter.length >= 18 && longer.includes(shorter)) return 0.94;

  const tokenSetA = new Set(contentSimilarityTokens(cleanA));
  const tokenSetB = new Set(contentSimilarityTokens(cleanB));
  if (!tokenSetA.size || !tokenSetB.size) return 0;

  let overlapCount = 0;
  for (const token of tokenSetA) {
    if (tokenSetB.has(token)) overlapCount += 1;
  }
  if (!overlapCount) return 0;

  const overlap = overlapCount / Math.min(tokenSetA.size, tokenSetB.size);
  const union = new Set([...tokenSetA, ...tokenSetB]).size;
  const jaccard = union ? overlapCount / union : 0;
  const seqA = cleanA.split(" ").filter(Boolean);
  const seqB = cleanB.split(" ").filter(Boolean);
  let leadingMatches = 0;
  for (let i = 0; i < Math.min(4, seqA.length, seqB.length); i += 1) {
    if (seqA[i] !== seqB[i]) break;
    leadingMatches += 1;
  }
  const leadBonus = leadingMatches >= 2 ? 0.12 : leadingMatches === 1 ? 0.05 : 0;
  return Math.min(1, Math.max(overlap, overlap * 0.7 + jaccard * 0.3) + leadBonus);
}

function recentAuthorContentExists(userId, text, { kind = "post", media = [], quotePostId = "", targetPostId = "", excludeId = "" } = {}) {
  const normalizedKind = kind === "reply" ? "reply" : "post";
  const signature = comparableDuplicateSignature({ text, kind: normalizedKind, media, quotePostId, targetPostId });
  if (!userId || !signature) return false;
  const now = Date.now();
  if (normalizedKind === "post") {
    return (posts || []).some((post) => {
      if (!post || post.authorId !== userId || post.hidden) return false;
      if (excludeId && String(post.id || "") === excludeId) return false;
      const createdAt = Date.parse(String(post.createdAt || ""));
      if (!Number.isFinite(createdAt) || now - createdAt > RECENT_DUPLICATE_CONTENT_WINDOW_MS) return false;
      return comparableDuplicateSignature({
        text: post.text,
        kind: "post",
        media: post.media,
        quotePostId: post.quotePostId,
      }) === signature;
    });
  }
  const walk = (replies, currentPostId = "") => {
    if (!Array.isArray(replies) || !replies.length) return false;
    for (const reply of replies) {
      if (!reply || reply.hidden) continue;
      if (excludeId && String(reply.id || "") === excludeId) continue;
      if (reply.authorId === userId) {
        const createdAt = Date.parse(String(reply.createdAt || ""));
        if (Number.isFinite(createdAt) && now - createdAt <= RECENT_DUPLICATE_CONTENT_WINDOW_MS) {
          if (comparableDuplicateSignature({ text: reply.text, kind: "reply", targetPostId: currentPostId }) === signature) return true;
        }
      }
      if (walk(reply.replies, currentPostId)) return true;
    }
    return false;
  };
  return (posts || []).some((post) => walk(post?.replies, post?.id));
}

function recentPostItemsByAuthor(now = Date.now()) {
  if (
    recentPostIndexCache &&
    recentPostIndexCache.byAuthor instanceof Map &&
    now - Number(recentPostIndexCache.builtAtMs || 0) < 30_000
  ) {
    return recentPostIndexCache.byAuthor;
  }
  const byAuthor = new Map();
  for (const post of posts || []) {
    if (!post || post.hidden) continue;
    const authorId = String(post.authorId || "").trim();
    const createdAt = Date.parse(String(post.createdAt || ""));
    if (authorId && Number.isFinite(createdAt) && now - createdAt <= RECENT_REPETITIVE_LOW_SIGNAL_WINDOW_MS) {
      const list = byAuthor.get(authorId) || [];
      list.push(post);
      byAuthor.set(authorId, list);
    }
  }
  for (const [authorId, list] of byAuthor.entries()) {
    byAuthor.set(authorId, trimRecentRepetitionItems(list));
  }
  recentPostIndexCache = { builtAtMs: now, byAuthor };
  return byAuthor;
}

function recentReplyItemsByAuthor(now = Date.now()) {
  if (
    recentReplyIndexCache &&
    recentReplyIndexCache.byAuthor instanceof Map &&
    now - Number(recentReplyIndexCache.builtAtMs || 0) < 30_000
  ) {
    return recentReplyIndexCache.byAuthor;
  }
  const byAuthor = new Map();
  const walk = (replies) => {
    if (!Array.isArray(replies) || !replies.length) return;
    for (const reply of replies) {
      if (!reply || reply.hidden) {
        if (reply?.replies) walk(reply.replies);
        continue;
      }
      const authorId = String(reply.authorId || "").trim();
      const createdAt = Date.parse(String(reply.createdAt || ""));
      if (authorId && Number.isFinite(createdAt) && now - createdAt <= RECENT_REPETITIVE_LOW_SIGNAL_WINDOW_MS) {
        const list = byAuthor.get(authorId) || [];
        list.push(reply);
        byAuthor.set(authorId, list);
      }
      if (reply?.replies) walk(reply.replies);
    }
  };
  for (const post of posts || []) walk(post?.replies);
  for (const [authorId, list] of byAuthor.entries()) {
    byAuthor.set(authorId, trimRecentRepetitionItems(list));
  }
  recentReplyIndexCache = { builtAtMs: now, byAuthor };
  return byAuthor;
}

function trimRecentRepetitionItems(items) {
  const list = Array.isArray(items) ? items.filter(Boolean) : [];
  if (list.length <= MAX_REPETITION_COMPARISON_ITEMS_PER_AUTHOR) return list;
  return list
    .slice()
    .sort(compareNewDescByCreatedAtThenId)
    .slice(0, MAX_REPETITION_COMPARISON_ITEMS_PER_AUTHOR);
}

function recentAuthorLowSignalRepetition(userId, text, { kind = "post", excludeId = "" } = {}) {
  const cleanText = String(text ?? "").trim();
  const currentIsThin = textLooksThinForRepetition(cleanText, kind);
  if (!userId || !cleanText) {
    return { similarCount: 0, similarLowSignalCount: 0, strongestSimilarity: 0, currentIsThin, shouldDemote: false, shouldBlock: false };
  }

  const now = Date.now();
  const recentItems = [];
  if (kind === "post") {
    const byAuthor = recentPostItemsByAuthor(now);
    const authorPosts = byAuthor.get(String(userId || "").trim()) || [];
    for (const post of authorPosts) {
      if (excludeId && String(post.id || "") === excludeId) continue;
      recentItems.push(post);
    }
  } else {
    const byAuthor = recentReplyItemsByAuthor(now);
    const authorReplies = byAuthor.get(String(userId || "").trim()) || [];
    for (const reply of authorReplies) {
      if (excludeId && String(reply.id || "") === excludeId) continue;
      recentItems.push(reply);
    }
  }

  let similarCount = 0;
  let similarLowSignalCount = 0;
  let strongestSimilarity = 0;
  for (const item of trimRecentRepetitionItems(recentItems)) {
    const similarity = contentSimilarityScore(cleanText, item?.text);
    if (similarity < REPETITIVE_LOW_SIGNAL_SIMILARITY_THRESHOLD) continue;
    similarCount += 1;
    strongestSimilarity = Math.max(strongestSimilarity, similarity);
    if (textLooksThinForRepetition(item?.text, kind)) similarLowSignalCount += 1;
  }

  const shouldDemote = currentIsThin && similarLowSignalCount >= 1;
  const shouldBlock = currentIsThin && similarLowSignalCount >= REPETITIVE_LOW_SIGNAL_BLOCK_COUNT && strongestSimilarity >= 0.82;
  return { similarCount, similarLowSignalCount, strongestSimilarity, currentIsThin, shouldDemote, shouldBlock };
}

function contentQualityIssue({ text, media = [], kind = "post", userId = "", quotePostId = "", targetPostId = "", excludeId = "" }) {
  return REQUEST_TIMING.measureSync("text_moderation", () => {
  const cleanText = String(text ?? "").trim();
  if (!cleanText) return "Missing text.";
  const nativeAbuse = nativeAbuseIssue({ posts, text: cleanText, kind, userId, targetPostId, excludeId });
  if (nativeAbuse) return nativeAbuse;
  const publicSafetyIssue = publicViolentIntentIssue(cleanText, kind);
  if (publicSafetyIssue) return publicSafetyIssue;
  const commandOnlyIssue = commandOnlyPublicTextIssue(cleanText, kind);
  if (commandOnlyIssue) return commandOnlyIssue;
  const urlCount = countInlineUrls(cleanText) + (Array.isArray(media) ? media.length : 0);
  const maxUrls = kind === "reply" ? MAX_INLINE_URLS_PER_REPLY : MAX_INLINE_URLS_PER_POST;
  if (kind === "post" && postLooksGreetingOnly(cleanText)) {
    return Array.isArray(media) && media.length
      ? "Add one clear line of context so the post can stand on its own."
      : "That post is too thin for the feed. Start with one specific question, observation, or lesson.";
  }
  if (textLooksObviousFiller(cleanText, kind)) {
    return kind === "reply"
      ? "That reply is too thin to help the conversation. Add a specific reaction, question, or piece of context."
      : "That post reads like filler. Add a specific question, observation, or lesson so it earns a place in the feed.";
  }
  if (urlCount > maxUrls) {
    return kind === "reply"
      ? "That reply has too many links. Keep replies focused and trim the attachments."
      : "That post has too many links. Keep posts focused and trim the attachments.";
  }
  const linkSpamIssue = excessiveInlineLinkSpamIssue(cleanText, kind);
  if (linkSpamIssue) return linkSpamIssue;
  const repetitiveJunkIssue = repetitiveJunkTextIssue(cleanText, kind);
  if (repetitiveJunkIssue) return repetitiveJunkIssue;
  if (recentAuthorContentExists(userId, cleanText, { kind, media, quotePostId, targetPostId, excludeId })) {
    return kind === "reply"
      ? (targetPostId
          ? "You already sent something very similar in this thread recently. Change the wording or add new context."
          : "You already sent something very similar recently. Change the wording or add new context.")
      : "You already posted something very similar recently. Change the wording or add new context.";
  }
  const repetition = recentAuthorLowSignalRepetition(userId, cleanText, { kind, excludeId });
  if (repetition.shouldBlock) {
    return kind === "reply"
      ? "You've already sent a few versions of this reply recently. Add a new detail or angle before sending it."
      : "You've already posted a few versions of this recently. Add a new detail or angle before publishing it.";
  }
  return "";
  });
}

async function mediaSafetyIssue(media) { return !media?.length ? '' : media.length === 1 && media[0].type === 'image' && runtime.allowedPhotoUrls?.includes(media[0].url) ? '' : 'Use a photo attached to this chat with the photo input. External attachments are unavailable; your post has not been published.'; }

const MEDIA_DNS_BUSY_ISSUE = "Media verification is busy. Try again shortly.";

function mediaDnsBusyActionResult() {
  return {
    ok: false,
    status: 503,
    code: "server_busy",
    retryAfterSec: 1,
    message: MEDIA_DNS_BUSY_ISSUE,
  };
}

const createPostMediaSafetyProofs = new WeakSet();

function createPostMediaSafetyFingerprint(media) {
  return stableStringify(Array.isArray(media) ? media : []);
}

async function preflightCreatePostMedia(media, { callerKey = "" } = {}) {
  const mediaValidation = validateAndSanitizeNewPostMediaList(media ?? []);
  if (mediaValidation.issue) {
    return { issue: mediaValidation.issue, media: [], proof: null };
  }

  const cleanMedia = mediaValidation.media;
  const mediaIssue = await mediaSafetyIssue(cleanMedia, { callerKey });
  if (mediaIssue) {
    return {
      issue: mediaIssue,
      media: [],
      proof: null,
      ...(mediaIssue === MEDIA_DNS_BUSY_ISSUE ? { error: mediaDnsBusyActionResult() } : {}),
    };
  }

  const proof = Object.freeze({ fingerprint: createPostMediaSafetyFingerprint(cleanMedia) });
  createPostMediaSafetyProofs.add(proof);
  return { issue: "", media: cleanMedia, proof };
}

function consumeCreatePostMediaSafetyProof(proof, media) {
  if (!proof || typeof proof !== "object" || !createPostMediaSafetyProofs.has(proof)) return false;
  createPostMediaSafetyProofs.delete(proof);
  return proof.fingerprint === createPostMediaSafetyFingerprint(media);
}

function getCallerKey(ctx) {
  if (isPublishedV2McpToolContext(ctx)) return "published-v2-public";
  const authenticatedUserId = authenticatedOAuthUserId(ctx);
  if (authenticatedUserId) return `oauth-user:${authenticatedUserId}`;
  const meta = ctx?._meta ?? {};
  if (!TURNFEED_TEST_NOAUTH_ENABLED) return "public-anonymous";
  return meta["openai/subject"] || meta["openai/session"] || "anon";
}

function getUserId(ctx) {
  if (isPublishedV2McpToolContext(ctx)) return "";
  const authenticatedUserId = authenticatedOAuthUserId(ctx);
  if (authenticatedUserId) return authenticatedUserId;
  if (!TURNFEED_TEST_NOAUTH_ENABLED) return "";
  return hashAnonId(getCallerKey(ctx));
}

function cleanDisplayName(name) {
  const s = String(name ?? "")
    .replace(/[\u0000-\u001F\u007F]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!s) return "";
  return s.slice(0, MAX_DISPLAY_NAME_CHARS);
}

function normalizedIdentityLabelKey(value) {
  return String(value ?? "")
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "");
}

