      if (timeRequest.error) return timeRequest.error;
      const digestFocus = FEED_DIGEST_FOCUSES.includes(args?.focus) ? args.focus
        : timeRequest.timeRange && timeRequest.timeRange.basis !== "activity" ? "latest"
          : inferOpenSocialFeedDigestFocus(timeRequest.targetText || "");
      // Published or cached ChatGPT metadata can omit the optional activity
      // window even when the user says "today". Make direct active digests
      // deterministic; broader ranked reading remains available through the
      // interesting focus and the open/start routing tools.
      const digestActivityWindow = timeRequest.timeRange ? "" : FEED_ACTIVITY_WINDOWS.includes(args?.activityWindow)
        ? args.activityWindow
        : digestFocus === "active"
          ? "past_24_hours"
          : "";
      const result = buildFeedDigestForTool(userId, {
        limit: args?.limit,
        focus: digestFocus,
        activityWindow: digestActivityWindow,
        timeRange: timeRequest.timeRange,
        cursor: args?.cursor,
      });
      const { message, ...structuredContent } = result;
