  const runCreatePostTool = async (args, ctx) => {
    const caller = getCallerKey(ctx);
    const userId = getUserId(ctx);
    const replyWithCreatePostReceipt = (result) => {
      const receipt = !legacyPublishedV2
        && result?.ok === true
        && result?.published === true
        && !String(result?.message || "").trim()
          ? { ...result, message: profiles?.[userId]?.privateAccount ? "Posted for your approved followers." : "Posted on Turnfeed." }
          : result;
      return replyWithActionResult(receipt, actionSyncExtraForUserId(userId, nativeCreatedPostReference(receipt, args, userId)));
    };
    const extraRateLimitResult = (rateLimitAction, options = {}) => mcpWriteRateLimitResult(rateLimitAction, options);
    const requestLimitResult = combinedRateLimitResultForAction("create_post:request", caller, extraRateLimitResult);
    if (requestLimitResult) {
      return replyWithActionResult(requestLimitResult, actionSyncExtraForUserId(userId));
    }
    if (!(await ensureFreshStore())) {
      return mcpStorageUnavailableResult({ strictOutput: strictToolOutput });
    }
    const existingRetry = existingCreatePostClientIdRetryResult({
      text: args?.text,
      media: args?.media,
      groupId: args?.groupId,
      quotePostId: args?.quotePostId,
      quoteRequested: createPostQuoteRequested(args),
      clientId: args?.clientId,
      userId,
    });
    if (existingRetry) return replyWithCreatePostReceipt(existingRetry);
    const limitPreview = combinedRateLimitPreviewForAction("create_post", caller, extraRateLimitResult);
    if (limitPreview) return replyWithActionResult(limitPreview, actionSyncExtraForUserId(userId));
    const mediaPreflight = await preflightCreatePostMedia(args?.media, { callerKey: caller });
    if (mediaPreflight.issue) {
      return replyWithActionResult(
        mediaPreflight.error || { ok: false, message: mediaPreflight.issue },
        actionSyncExtraForUserId(userId)
      );
    }
    const runCreatePost = () => handleCreatePost({
      text: args?.text,
      media: mediaPreflight.media,
      mediaSafetyProof: mediaPreflight.proof,
      groupId: args?.groupId,
      quotePostId: args?.quotePostId,
      quoteTargetLabel: args?.quoteTargetLabel,
      quoteAuthorName: args?.quoteAuthorName,
      quoteAuthorHandle: args?.quoteAuthorHandle,
      quotePostText: args?.quotePostText,
      quoteCreatedAt: args?.quoteCreatedAt,
      clientId: args?.clientId,
      userId,
      callerKey: caller,
      requireConfirmation: false,
      requireReadableQuoteTarget: !legacyPublishedV2,
      extraRateLimitResult,
    });
    const result = await mutateStore(runCreatePost);
    return replyWithCreatePostReceipt(result);
  };

